CREATE TABLE users (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    name VARCHAR(100) NOT NULL,
    email VARCHAR(150) NOT NULL UNIQUE,
    password VARCHAR(255) NOT NULL,
    role ENUM('ADMIN','TEACHER','STUDENT') NOT NULL,
    status TINYINT(1) NOT NULL DEFAULT 1,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE teachers (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL UNIQUE, employee_code VARCHAR(50) NOT NULL UNIQUE, phone VARCHAR(20), qualification VARCHAR(150), joining_date DATE, department VARCHAR(100), FOREIGN KEY (user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE students (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL UNIQUE, admission_no VARCHAR(50) NOT NULL UNIQUE, roll_no VARCHAR(50), phone VARCHAR(20), dob DATE, gender ENUM('MALE','FEMALE','OTHER'), address TEXT, admission_date DATE, FOREIGN KEY (user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE classes (id BIGINT PRIMARY KEY AUTO_INCREMENT, class_name VARCHAR(50) NOT NULL, academic_year VARCHAR(20) NOT NULL, status TINYINT(1) NOT NULL DEFAULT 1, UNIQUE(class_name,academic_year)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE sections (id BIGINT PRIMARY KEY AUTO_INCREMENT, class_id BIGINT NOT NULL, section_name VARCHAR(20) NOT NULL, FOREIGN KEY (class_id) REFERENCES classes(id), UNIQUE(class_id,section_name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE subjects (id BIGINT PRIMARY KEY AUTO_INCREMENT, subject_code VARCHAR(30) NOT NULL UNIQUE, subject_name VARCHAR(100) NOT NULL, max_marks INT NOT NULL DEFAULT 100, status TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
